#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-08

# strict-mode: opt-out a fault-arm probe must OBSERVE non-zero gate exits, not
# die on them, so it runs `set -uo pipefail` without -e like every other probe
# under tests/*/fault-arms/.
#
# Gate: tests/plugins/test-codex-plugin.sh
#
# Pass condition: exit 0. These arms cover the mech profile added in #4002. The
# failure they exist for is a profile that still looks fine to a reader while
# codex-cli would either reject it outright or run the worker unsandboxed:
#
#   fault   the profile file is gone. The gate must not treat "no profile" as
#           "nothing to check", which is how the pi manifest was silently absent.
#   fault2  sandbox_mode flipped to danger-full-access. The file parses, the
#           key set is unchanged, and the unattended worker now has the whole
#           machine.
#   fault3  a legacy [profiles.ork-mech] table appended. Measured on codex-cli
#           0.153.4: `--profile ork-mech` then dies at config load, so a green
#           gate here would ship a profile nobody can use.
#   fault4  the installer loses its legacy-table refusal, which is the check
#           that keeps a fresh machine off fault3's error.
#   fault5  the profile is on disk but the manifest stops naming it, which is
#           the two-sources-of-truth drift with no warning.
#
# The fixture copies the real src/ and plugins/ codex trees rather than
# synthesising them: the gate diffs source against built output, so a
# hand-built fixture would fail for the wrong reason.
set -uo pipefail

REPO="${REPO:?set by the fault-arms runner}"
GATE="$REPO/tests/plugins/test-codex-plugin.sh"
FIX="$H/fixtures/codex-plugin"
PROFILE="profiles/ork-mech.config.toml"

rm -rf "$FIX"

build_tree() {
  local dir="$1"
  mkdir -p "$dir/src/codex" "$dir/plugins" "$dir/tests" "$dir/.agents/plugins" "$dir/manifests/codex"
  cp -R "$REPO/src/codex/ork-codex" "$dir/src/codex/ork-codex"
  cp -R "$REPO/plugins/ork-codex" "$dir/plugins/ork-codex"
  cp -R "$REPO/tests/plugins" "$dir/tests/plugins"
  cp "$REPO/.agents/plugins/marketplace.json" "$dir/.agents/plugins/marketplace.json"
  cp "$REPO/package.json" "$dir/package.json"
  cp "$REPO/manifests/codex/ork-codex.json" "$dir/manifests/codex/ork-codex.json"
}

# Mutate BOTH copies: the gate's own source-vs-built diff would otherwise fail
# for a parity reason instead of the reason under test.
both() {
  local dir="$1" cmd="$2"
  local target
  for target in "$dir/src/codex/ork-codex" "$dir/plugins/ork-codex"; do
    eval "$cmd"
  done
}

# control: the shipped shape.
build_tree "$FIX/control"

# fault: the profile file is absent.
build_tree "$FIX/fault"
both "$FIX/fault" 'rm -f "$target/$PROFILE"'

# fault2: the file parses and keeps its key set, but drops the sandbox.
build_tree "$FIX/fault2"
both "$FIX/fault2" 'sed -e "s/^sandbox_mode = \"workspace-write\"/sandbox_mode = \"danger-full-access\"/" "$target/$PROFILE" > "$target/$PROFILE.new" && mv "$target/$PROFILE.new" "$target/$PROFILE"'

# fault3: a legacy [profiles.ork-mech] table, which codex rejects under --profile.
build_tree "$FIX/fault3"
both "$FIX/fault3" 'printf "\n[profiles.ork-mech]\napproval_policy = \"never\"\n" >> "$target/$PROFILE"'

# fault4: the installer stops refusing the legacy table.
build_tree "$FIX/fault4"
both "$FIX/fault4" 'grep -v "legacy \[profiles\." "$target/scripts/install-codex-profile.sh" > "$target/scripts/i.new" && mv "$target/scripts/i.new" "$target/scripts/install-codex-profile.sh" && chmod +x "$target/scripts/install-codex-profile.sh"'

# fault5: the manifest stops naming the profile that is still on disk.
build_tree "$FIX/fault5"
python3 - "$FIX/fault5/manifests/codex/ork-codex.json" <<'PYX'
import json, sys
from pathlib import Path
p = Path(sys.argv[1])
d = json.loads(p.read_text())
d.pop("profiles", None)
p.write_text(json.dumps(d, indent=2) + "\n")
PYX

run_arm() {
  CLAUDE_PROJECT_DIR="$1" bash "$GATE" >"$2" 2>&1
}

run_arm "$FIX/control" "$FIX/control.log"; control_rc=$?
run_arm "$FIX/fault"   "$FIX/fault.log";   fault_rc=$?
run_arm "$FIX/fault2"  "$FIX/fault2.log";  fault2_rc=$?
run_arm "$FIX/fault3"  "$FIX/fault3.log";  fault3_rc=$?
run_arm "$FIX/fault4"  "$FIX/fault4.log";  fault4_rc=$?
run_arm "$FIX/fault5"  "$FIX/fault5.log";  fault5_rc=$?

{
  echo "--- control tail ---"; tail -3 "$FIX/control.log"
  echo "--- fault tail ---";   tail -3 "$FIX/fault.log"
  echo "--- fault2 tail ---";  tail -3 "$FIX/fault2.log"
  echo "--- fault3 tail ---";  tail -3 "$FIX/fault3.log"
  echo "--- fault4 tail ---";  tail -3 "$FIX/fault4.log"
  echo "--- fault5 tail ---";  tail -3 "$FIX/fault5.log"
} >&2

printf 'RESULT gate=%s control=%s fault=%s fault2=%s fault3=%s fault4=%s fault5=%s\n' \
  "codex-plugin" "$control_rc" "$fault_rc" "$fault2_rc" "$fault3_rc" "$fault4_rc" "$fault5_rc"
